// data.json: قاعده البيانات مجرد تخزين بينات هنديهاله
//db:الوسيط بينهم بيعرف يقرا لبينات ويعدل ويضيف
//index.js:بيستقبل الطلبات من اليوزر وبيستدعي الدوال من db.js


import path from "path"
const dbpath= path.join(import.meta.dirname,"data.json")//وظيفته إنه يحدد مكان ملف data.json ويحفظ المسار في متغير اسمه dbpath.
//path.join("folder", "file.txt");
import fs from "fs/promises"
 export function createDB(){
return{
// id

    async getBYID(resource,id){
    const data= await fs.readFile(dbpath,"utf-8");
    const json= JSON.parse(data);
    return json[resource].find(x=>x.id===id);
},

// all
  async getAll(resource){
const data=   await fs.readFile(dbpath,"utf-8");
    const json= JSON.parse(data);
    return json[resource];
},


async create(resource,object){
const data= await fs.readFile(dbpath,"utf-8");
const json= JSON.parse(data);
const newresource=[...json[resource],{...object,id : getId()}];//...json[resource] = كل البيانات القديمة للـ resource
await fs.writeFile(dbpath, JSON.stringify(json));
const newData={
    ...json,
    [resource]:newresource
}
await fs.writeFile(dbpath, JSON.stringify(newData));
},


async update(resource,id,updates){
const data= await fs.readFile(dbpath,"utf-8");
const json= JSON.parse(data);

 const newresource= json[resource].map(x=>{//map() بتلف على كل عنصر في الـ Array.
    if(x.id!=id)
        { return x; }
    else{ return{ ...x, ...updates, id:x.id}; }
 }) ;
// json = كل البيانات القديمة.
// resource = الجزء اللي عايزين نغيره.
// newresource = البيانات الجديدة للجزء ده.
const newData={
    ...json,
    [resource]:newresource
}
await fs.writeFile(dbpath, JSON.stringify(newData));
},
 

async delete(resource,id){
const data= await fs.readFile(dbpath,"utf-8");
const json= JSON.parse(data);
 const newresource= json[resource].filter(x=>x.id!==id);

// json = كل البيانات القديمة.
// resource = الجزء اللي عايزين نغيره.
// newresource = البيانات الجديدة للجزء ده.
const newData={
    ...json,
    [resource]:newresource
}

await fs.writeFile(dbpath, JSON.stringify(newData));

}
}


}

function getId(){
    return  String(Math.floor(Math.random()*100000000));
}